"use strict";

// Translations. English text is the key: T("Start the quiz") returns the
// translation for the current language, or the English text if there isn't
// one. Placeholders like {branch} are filled from `vars`. Language files
// (lang/<code>.js, generated by tools/build_langs.py) set window.I18N_DATA
// before this file loads.

const LANGUAGES = [
  ["en", "English"], ["es", "Español"], ["tl", "Tagalog"], ["vi", "Tiếng Việt"], ["zh", "中文"],
  ["ko", "한국어"], ["fr", "Français"], ["pt", "Português"], ["ar", "العربية"],
];

const LANG = window.I18N_LANG || "en";
const I18N = window.I18N_DATA || {};

function T(text, vars) {
  const out = (LANG !== "en" && I18N[text]) || text;
  return vars ? out.replace(/\{(\w+)\}/g, (m, k) => (k in vars ? vars[k] : m)) : out;
}

// Translates every string in the content objects in place, using the same
// dictionary. Fields that hold codes, colors, ids or links are left alone.
const UNTRANSLATED_FIELDS = new Set(["id", "code", "color", "icon", "tr", "source", "key", "src"]);

function translateContent(...roots) {
  if (LANG === "en") return;
  const walk = (obj) => {
    if (Array.isArray(obj)) {
      obj.forEach((v, i) => { if (typeof v === "string") obj[i] = T(v); else if (v && typeof v === "object") walk(v); });
      return;
    }
    for (const [k, v] of Object.entries(obj)) {
      if (UNTRANSLATED_FIELDS.has(k)) continue;
      if (typeof v === "string") obj[k] = T(v);
      else if (v && typeof v === "object") walk(v);
    }
  };
  roots.forEach((r) => r && walk(r));
}

function setLanguage(code) {
  try { localStorage.setItem("rankedbingo.lang", code); } catch { /* not saved */ }
  location.reload();
}
